def sum_to(n):
    total = 0
    for i in range(1, n + 1):
        total += i
    return total

def evens_only(xs):
    out = []
    for x in xs:
        if x % 2 == 0:
            out.append(x)
    return out

def count_vowels(s):
    count = 0
    for ch in s.lower():
        if ch in "aeiou":
            count += 1
    return count

